type Stack[T any] []T

func (s *Stack[T]) Push(value T) {
	*s = append(*s, value)
}

func (s *Stack[T]) Pop() T {
	last := len(*s) - 1
	value := (*s)[last]
	*s = (*s)[:last]
	return value
}

